import React, { useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import Button from "../components/common/Button";
import { useUI } from "../context/UIContext";
import styles from "../Result.module.css";
import { saveToSheet } from "../components/utils/googleSheetLogger";

// 🚀 引入剛做好的獨立問卷組件
import DcsSurvey from "../components/DcsSurvey";

const Result = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { setHeroData, allAnswers } = useUI();
  const { finalData } = location.state || {};

  // 狀態管理
  const [isFlowModalOpen, setIsFlowModalOpen] = useState(false);
  const [isSurveyOpen, setIsSurveyOpen] = useState(false); // 控制問卷是否開啟
  const [isSurveyCompleted, setIsSurveyCompleted] = useState(false);

  const flowCharts = {
    BCT: "https://sdm-5cbs.onrender.com/assets/images/bct.png",
    SM: "https://sdm-5cbs.onrender.com/assets/images/sm.png",
  };

  useEffect(() => {
    if (!finalData) return;

    setHeroData({
      step: 3,
      currentStep: 3,
      imageUrl:
        "https://web-production-fbb7b.up.railway.app/static/helperinside.png",
      title: "第三步驟：評估結果建議",
      description: `${allAnswers.userName || "您"}您好，依據您的選擇，醫療團隊為您整理的建議方案是：${finalData.title}。這最符合您目前的價值偏好。`,
      audioText: `${allAnswers.userName || "您"}您好，依據您的選擇，醫療團隊為您整理的建議方案是：${finalData.title}。這最符合您目前的價值偏好。`,
      autoPlay: true,
      speak: true,
    });
  }, [setHeroData, finalData, allAnswers.userName]);

  const handleSurveyComplete = async (finalDcsAnswers) => {
    setIsSurveyCompleted(true);
    setIsSurveyOpen(false); // 關閉容器內滿版問卷

    // 背景靜態上傳 Sheets
    try {
      const logData = {
        date: new Date().toLocaleDateString(),
        userName: allAnswers.userName,
        birthDate: allAnswers.birthday || allAnswers.birthDate,
        selectedTopic: allAnswers.selectedTopic,
        details: JSON.stringify(allAnswers.answers),
        finalResult: finalData.title,
        dcsScore: JSON.stringify(finalDcsAnswers),
      };
      await saveToSheet(logData);
    } catch (error) {
      console.error("資料同步失敗", error);
    }
  };

  if (!finalData) return null; // 簡化忽略

  let displayType =
    finalData.type || (finalData.title?.includes("部分") ? "BCT" : "SM");
  const chartUrl = flowCharts[displayType];

  return (
    // 💡 確保在 Result.module.css 中的 .container 加上了 position: relative; overflow: hidden;
    <div
      className={styles.container}
      style={{ position: "relative", overflow: "hidden" }}
    >
      {/* 🚀 關鍵核心：當使用者點選填寫時，問卷直接就地在 container 內以 absolute 撐滿 */}
      {isSurveyOpen && (
        <DcsSurvey
          onComplete={handleSurveyComplete}
          onClose={() => setIsSurveyOpen(false)}
        />
      )}

      {/* 建議方案卡片 */}
      <div className={styles.resultCard}>
        <h2 className={styles.resultTitle}>{finalData.title}</h2>
        <hr className={styles.divider} />
        <div
          className={styles.description}
          dangerouslySetInnerHTML={{ __html: finalData.description }}
        />
      </div>

      {/* 質感互動功能區 */}
      <div style={interactiveGroupStyle}>
        {chartUrl && (
          <button
            onClick={() => setIsFlowModalOpen(true)}
            style={secondaryPinkButtonStyle}
          >
            🔍 查看您的預計治療流程
          </button>
        )}

        <div style={surveyCardStyle(isSurveyCompleted)}>
          <p style={surveyTitleStyle(isSurveyCompleted)}>
            {isSurveyCompleted
              ? "✅ 填寫完成！醫療團隊已收到您的回饋"
              : "最後一步：請填寫決策評估問卷"}
          </p>
          <p style={surveySubTextStyle}>
            {isSurveyCompleted
              ? "感謝您協助我們提升醫療輔助品質。"
              : "填寫此問卷能幫助我們了解這項工具對您的幫助。"}
          </p>
          {!isSurveyCompleted && (
            <button
              onClick={() => setIsSurveyOpen(true)}
              style={primaryPinkButtonStyle}
            >
              點此開始互動問卷
            </button>
          )}
        </div>
      </div>

      {/* 底部導覽按鈕 */}
      <div
        style={{
          width: "100%",
          maxWidth: "480px",
          padding: "0 16px",
          boxSizing: "border-box",
          marginTop: "auto",
        }}
      >
        <Button
          style={{ width: "100%", height: "50px", borderRadius: "25px" }}
          onClick={() => navigate("/selection")}
          isDisabled={!isSurveyCompleted}
        >
          {isSurveyCompleted ? "完成並回首頁" : "請先完成上方問卷以解鎖結束"}
        </Button>
      </div>

      {/* 預計治療流程 Modal 依舊維持傳統大視窗彈出 */}
      {isFlowModalOpen && (
        <div
          onClick={() => setIsFlowModalOpen(false)}
          style={modalOverlayStyle}
        >
          <div onClick={(e) => e.stopPropagation()} style={modalContentStyle}>
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                marginBottom: "15px",
              }}
            >
              <h3 style={{ margin: 0, color: "#4a4a4a" }}>您的預計治療流程</h3>
              <button
                onClick={() => setIsFlowModalOpen(false)}
                style={closeButtonStyle}
              >
                ✕
              </button>
            </div>
            <div style={{ maxHeight: "55vh", overflowY: "auto" }}>
              <img
                src={chartUrl}
                alt="治療流程圖"
                style={{ width: "100%", height: "auto", display: "block" }}
              />
            </div>
            <div style={{ marginTop: "20px", display: "flex", gap: "12px" }}>
              <button
                style={modalPrimaryButtonStyle}
                onClick={() => window.print()}
              >
                🖨️ 列印 / 儲存 PDF
              </button>
              <button
                style={modalSecondaryButtonStyle}
                onClick={() => setIsFlowModalOpen(false)}
              >
                關閉
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// 行內樣式保持不變...
const interactiveGroupStyle = {
  width: "100%",
  maxWidth: "480px",
  padding: "0 16px",
  margin: "10px 0 25px 0",
  boxSizing: "border-box",
};
const secondaryPinkButtonStyle = {
  width: "100%",
  padding: "14px",
  backgroundColor: "#fff",
  border: "1.5px solid #e89abe",
  borderRadius: "25px",
  color: "#e89abe",
  fontSize: "0.98rem",
  fontWeight: "600",
  cursor: "pointer",
  marginBottom: "20px",
};
const surveyCardStyle = (completed) => ({
  padding: "22px 20px",
  backgroundColor: completed ? "#f6ffed" : "#fff",
  border: `1px solid ${completed ? "#b7eb8f" : "#f5efe3"}`,
  borderRadius: "18px",
  textAlign: "center",
  boxShadow: "0 4px 16px rgba(0,0,0,0.03)",
});
const surveyTitleStyle = (completed) => ({
  fontWeight: "600",
  color: completed ? "#52c41a" : "#4a4a4a",
  fontSize: "1.05rem",
  margin: "0 0 6px 0",
});
const surveySubTextStyle = {
  fontSize: "0.88rem",
  color: "#8c8c8c",
  margin: "0 0 16px 0",
  lineHeight: "1.4",
};
const primaryPinkButtonStyle = {
  width: "80%",
  padding: "12px 24px",
  backgroundColor: "#e89abe",
  border: "none",
  borderRadius: "22px",
  color: "#fff",
  fontSize: "0.98rem",
  fontWeight: "600",
  cursor: "pointer",
};
const modalOverlayStyle = {
  position: "fixed",
  top: 0,
  left: 0,
  right: 0,
  bottom: 0,
  backgroundColor: "rgba(0,0,0,0.45)",
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
